/** Guide attribution lasts one hour in this tab, including the OAuth round trip. */
const ORIGIN_KEY = 'palpitae:origem-guia'
const ORIGIN_TTL_MS = 60 * 60 * 1000

// Match the CTA tokens generated by build/guides.ts without importing build code.
function validOrigin(value: unknown): value is string {
  return (
    typeof value === 'string' &&
    value.length <= 100 &&
    /^(?:guias_header|guia_[a-z0-9]+(?:-[a-z0-9]+){0,11}(?:_header)?)$/.test(value)
  )
}

export function clearGuideOrigin(): void {
  try {
    sessionStorage.removeItem(ORIGIN_KEY)
  } catch {
    /* Storage is optional. */
  }
}

/** A new invalid token clears previous attribution; a missing token preserves it. */
export function captureGuideOrigin(search: string): string | undefined {
  const params = new URLSearchParams(search)
  if (!params.has('from')) return undefined
  const origin = params.get('from')
  if (params.getAll('from').length !== 1 || !validOrigin(origin)) {
    clearGuideOrigin()
    return undefined
  }
  try {
    sessionStorage.setItem(ORIGIN_KEY, JSON.stringify({ origin, capturedAt: Date.now() }))
  } catch {
    /* Navigation and tracking arrival still work without storage. */
  }
  return origin
}

export function getGuideOrigin(): string | undefined {
  try {
    const stored = sessionStorage.getItem(ORIGIN_KEY)
    if (!stored) return undefined
    const data = JSON.parse(stored) as { origin?: unknown; capturedAt?: unknown }
    if (
      validOrigin(data?.origin) &&
      typeof data.capturedAt === 'number' &&
      Number.isFinite(data.capturedAt) &&
      data.capturedAt <= Date.now() &&
      Date.now() - data.capturedAt < ORIGIN_TTL_MS
    )
      return data.origin
    clearGuideOrigin()
  } catch {
    clearGuideOrigin()
  }
  return undefined
}
